app.UseAntiforgery();

// Set hardcoded authentication state for the simulated user
app.Use(async (context, next) =>
{
    var authStateProvider = context.RequestServices.GetRequiredService<AuthenticationStateProvider>()
        as PersistingAuthenticationStateProvider;

    if (authStateProvider is not null)
    {
        var claims = new List<Claim>
        {
            new(ClaimTypes.Name, "bob@example.com"),
            new(ClaimTypes.Email, "bob@example.com"),
            new(ClaimTypes.Role, "User"),
            new(ClaimTypes.Role, "Editor"),
        };
        var identity = new ClaimsIdentity(claims, "HardcodedAuth");
        var principal = new ClaimsPrincipal(identity);
        authStateProvider.SetAuthenticationState(
            Task.FromResult(new AuthenticationState(principal)));
    }

    await next();
});

app.MapStaticAssets();

